schema:
{
  "description": "Relazioni trimestrali in Word",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "estimateFieldSourceAndConfidence": true
  },
  "fieldSchema": {
    "fields": {
      "RicaviPerArea": {
        "type": "array",
        "description": "Una voce per ogni riga della tabella Area/Ricavi/Margine.",
        "items": {
          "type": "object",
          "properties": {
            "Area": {
              "type": "string"
            },
            "Ricavi": {
              "type": "number"
            },
            "MarginePercento": {
              "type": "number"
            }
          }
        }
      },
      "RicaviQ3Testo": {
        "type": "number",
        "method": "extract",
        "description": "Ricavi complessivi del terzo trimestre citati nel testo."
      },
      "UnitaDiMisura": {
        "type": "string",
        "method": "classify",
        "enum": [
          "euro",
          "migliaia di euro",
          "milioni di euro",
          "altro"
        ],
        "description": "Unità dei valori, dalla nota a piè di pagina."
      }
    }
  }
}
